print("=== TOP section (cols 0-5), rows 2-5 ===")
for c in range(6):
    seq = col_seq(2, 6, c, grid)
    print(f"Col {c}: {seq}")

print("\n=== BOTTOM section (cols 0-5), rows 14-17 ===")
for c in range(6):
    seq = col_seq(14, 18, c, grid)
    print(f"Col {c}: {seq}")

# Now look at the wider pattern - is there a grouping?
