    print(f"Row {r} cols 12-27: {row_slice}")

print("\n=== BOTTOM section columns 12-27 ===")
for r in range(14, 18):
    row_slice = grid[r][12:28]
    print(f"Row {r} cols 12-27: {row_slice}")

# Check specific column pairs
print("\n=== TOP col 12 vs BOTTOM cols ===")
for c in range(12, 28):
    bot_seq = tuple(grid[r][c] for r in range(14, 18))
    top_12 = tuple(grid[r][12] for r in range(2, 6))
    if bot_seq == top_12:
        print(f"BOTTOM col {c} == TOP col 12")

print("\n=== Lookup: where does TOP col 0 appear in TOP? ===")
for c in range(6, 28):
    if tuple(grid[r][c] for r in range(2, 6)) == tuple(grid[r][0] for r in range(2, 6)):
        print(f"TOP col {c} == TOP col 0")

# Test hypothesis: output = 7 where either TOP or BOTTOM has 7
# This would make the filled cells the union of both patterns

def predicted_output():
    result = [[0]*28 for _ in range(23)]

    for r in range(23):
        for c in range(28):
            top_val = grid[r][c] if r < 6 else (grid[r][c] if r >= 14 else 0)
            bottom_val = grid[r][c] if r >= 14 else (grid[r][c] if r < 6 else 0)

            # If either top or bottom has a 7, output 7
            if top_val == 7 or bottom_val == 7:
                result[r][c] = 7
            else:
                result[r][c] = 0
    return result

prediction = predicted_output()
