# Check if this looks right
print("\n=== Output rows 14-17 (the completed bottom section) ===")
for r in range(14, 18):
    print(f"Row {r}: {prediction[r]}")

# Hypothesis: Output is the INTERSECTION - 7 only where BOTH top section AND bottom section have 7

def predict_intersection():
    result = [[0]*28 for _ in range(23)]

    for r in range(2, 6):
        top_row = grid[r]
        bot_row = grid[r+12]

        for c in range(28):
